package com.example.backend.service;
import com.example.backend.entity.Task; import com.example.backend.repository.TaskRepository; import org.junit.jupiter.api.Test; import java.util.Optional; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*;
class TaskServiceTest { @Test void togglesExistingTaskAndPersistsIt(){TaskRepository repository=mock(TaskRepository.class);Task task=new Task("Read model",false);when(repository.findById(7L)).thenReturn(Optional.of(task));when(repository.save(task)).thenReturn(task);Task updated=new TaskService(repository).toggleTask(7L);assertThat(updated.isCompleted()).isTrue();verify(repository).save(task);} @Test void missingTaskReturnsNull(){TaskRepository repository=mock(TaskRepository.class);when(repository.findById(404L)).thenReturn(Optional.empty());assertThat(new TaskService(repository).toggleTask(404L)).isNull();verify(repository,never()).save(any());} }
